{
  "name": "entire-cli-e2e",
  "version": "1.0.0",
  "description": "E2E tests for Entire CLI using Claude Agent SDK",
  "type": "module",
  "scripts": {
    "test": "vitest run",
    "test:watch": "vitest watch"
  },
  "devDependencies": {
    "@anthropic-ai/claude-code": "^1.0.0",
    "@types/node": "^22.10.0",
    "typescript": "^5.7.0",
    "vitest": "^3.0.0"
  },
  "engines": {
    "node": ">=20.0.0"
  }
}

import { defineConfig } from 'vitest/config';

export default defineConfig({
  test: {
    // Global setup builds CLI binary before tests
    globalSetup: ['./src/setup/global-setup.ts'],

    // Test configuration
    include: ['src/tests/**/*.test.ts'],

    // 2-minute timeout per test (Claude can be slow)
    testTimeout: 120_000,

    // Sequential execution to avoid API rate limits
    pool: 'forks',
    poolOptions: {
      forks: {
        singleFork: true,
      },
    },

    // TypeScript support
    typecheck: {
      enabled: false,
    },

    // Environment
    env: {
      NODE_ENV: 'test',
    },
  },
});

import { execSync } from 'node:child_process';
import { mkdtempSync, existsSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';

/**
 * Global setup runs once before all tests.
 * Builds the CLI binary and sets environment variables for test utilities.
 */
export default async function globalSetup(): Promise<() => void> {
  const projectRoot = resolve(import.meta.dirname, '../../..');
  const tempDir = mkdtempSync(join(tmpdir(), 'entire-e2e-'));
  const binaryPath = join(tempDir, 'entire');

  console.log(`Building CLI binary to ${binaryPath}...`);

  // Build the CLI binary with version info
  const buildCmd = `
    VERSION=$(git describe --tags --always --dirty 2>/dev/null || echo "e2e-test")
    COMMIT=$(git rev-parse --short HEAD 2>/dev/null || echo "unknown")
    go build -ldflags "-X entire.io/cli/cmd/entire/cli.Version=\${VERSION} -X entire.io/cli/cmd/entire/cli.Commit=\${COMMIT}" -o "${binaryPath}" ./cmd/entire
  `;

  try {
    execSync(buildCmd, {
      cwd: projectRoot,
      shell: '/bin/bash',
      stdio: 'inherit',
    });
  } catch (error) {
    console.error('Failed to build CLI binary');
    throw error;
  }

  if (!existsSync(binaryPath)) {
    throw new Error(`CLI binary not found at ${binaryPath}`);
  }

  console.log('CLI binary built successfully');

  // Set environment variable for test utilities
  process.env.ENTIRE_BIN_PATH = binaryPath;
  process.env.ENTIRE_PROJECT_ROOT = projectRoot;

  // Return teardown function
  return () => {
    console.log(`Cleaning up temp directory: ${tempDir}`);
    try {
      execSync(`rm -rf "${tempDir}"`, { stdio: 'ignore' });
    } catch {
      // Ignore cleanup errors
    }
  };
}

import { execSync, type ExecSyncOptions } from 'node:child_process';
import {
  mkdtempSync,
  writeFileSync,
  readFileSync,
  existsSync,
  rmSync,
  mkdirSync,
} from 'node:fs';
import { tmpdir } from 'node:os';
import { join, dirname } from 'node:path';

/**
 * TestRepo provides isolated git repository management for E2E tests.
 * Each instance creates a fresh temp directory with an initialized git repo.
 */
export class TestRepo {
  public readonly path: string;
  private _cleaned = false;

  constructor() {
    // Create unique temp directory for this test
    this.path = mkdtempSync(join(tmpdir(), 'entire-e2e-repo-'));

    // Initialize git repository
    this.git('init');
    this.git('config', 'user.email', 'test@example.com');
    this.git('config', 'user.name', 'Test User');

    // Create initial commit so HEAD exists
    this.writeFile('.gitignore', '.entire/\n');
    this.git('add', '.gitignore');
    this.git('commit', '-m', 'Initial commit');
  }

  /**
   * Execute a git command in the repo directory.
   */
  git(...args: string[]): string {
    const options: ExecSyncOptions = {
      cwd: this.path,
      encoding: 'utf-8',
      stdio: ['pipe', 'pipe', 'pipe'],
    };

    try {
      const result = execSync(`git ${args.map(a => `"${a}"`).join(' ')}`, {
        ...options,
        shell: '/bin/bash',
      });
      return (result as string).trim();
    } catch (error) {
      const execError = error as { stderr?: Buffer | string };
      const stderr = execError.stderr?.toString() || '';
      throw new Error(`git ${args.join(' ')} failed: ${stderr}`);
    }
  }

  /**
   * Get the current HEAD commit hash.
   */
  getHeadHash(): string {
    return this.git('rev-parse', 'HEAD');
  }

  /**
   * Get the short (7-char) HEAD commit hash.
   */
  getHeadHashShort(): string {
    return this.git('rev-parse', '--short=7', 'HEAD');
  }

  /**
   * Check if a branch exists.
   */
  branchExists(branchName: string): boolean {
    try {
      this.git('rev-parse', '--verify', branchName);
      return true;
    } catch {
      return false;
    }
  }

  /**
   * List all branches (including remote-style refs).
   */
  listBranches(): string[] {
    const output = this.git('branch', '-a');
    return output
      .split('\n')
      .map(line => line.replace(/^\*?\s+/, '').trim())
      .filter(Boolean);
  }

  /**
   * Get file content at a specific ref (branch/commit).
   */
  getFileAtRef(ref: string, filePath: string): string | null {
    try {
      return this.git('show', `${ref}:${filePath}`);
    } catch {
      return null;
    }
  }

  /**
   * List files in a tree at a specific ref.
   */
  listFilesAtRef(ref: string, path = ''): string[] {
    try {
      const treePath = path ? `${ref}:${path}` : ref;
      const output = this.git('ls-tree', '-r', '--name-only', treePath);
      return output.split('\n').filter(Boolean);
    } catch {
      return [];
    }
  }

  /**
   * Write a file to the working directory.
   */
  writeFile(relativePath: string, content: string): void {
    const fullPath = join(this.path, relativePath);
    const dir = dirname(fullPath);
    if (!existsSync(dir)) {
      mkdirSync(dir, { recursive: true });
    }
    writeFileSync(fullPath, content, 'utf-8');
  }

  /**
   * Read a file from the working directory.
   */
  readFile(relativePath: string): string {
    const fullPath = join(this.path, relativePath);
    return readFileSync(fullPath, 'utf-8');
  }

  /**
   * Check if a file exists in the working directory.
   */
  fileExists(relativePath: string): boolean {
    return existsSync(join(this.path, relativePath));
  }

  /**
   * Create a commit with the given message (stages all changes).
   */
  commit(message: string): string {
    this.git('add', '-A');
    this.git('commit', '-m', message);
    return this.getHeadHash();
  }

  /**
   * Get the commit message of a specific ref.
   */
  getCommitMessage(ref: string): string {
    return this.git('log', '-1', '--format=%B', ref);
  }

  /**
   * Get commit trailers from a specific ref.
   */
  getCommitTrailers(ref: string): Map<string, string> {
    const message = this.getCommitMessage(ref);
    const trailers = new Map<string, string>();

    // Parse trailers from the end of commit message
    const lines = message.split('\n');
    for (const line of lines) {
      const match = line.match(/^([A-Za-z-]+):\s*(.+)$/);
      if (match) {
        trailers.set(match[1], match[2]);
      }
    }

    return trailers;
  }

  /**
   * Get log of commits for a branch.
   */
  getLog(ref: string, count = 10): string[] {
    const output = this.git('log', `--format=%H %s`, `-${count}`, ref);
    return output.split('\n').filter(Boolean);
  }

  /**
   * Clean up the temporary directory.
   */
  cleanup(): void {
    if (this._cleaned) return;
    this._cleaned = true;

    try {
      rmSync(this.path, { recursive: true, force: true });
    } catch {
      // Ignore cleanup errors
    }
  }
}

/**
 * Create a fresh test repository for a test.
 * Use with afterEach to ensure cleanup.
 */
export function createTestRepo(): TestRepo {
  return new TestRepo();
}

import { execSync, type ExecSyncOptions } from 'node:child_process';

export interface RewindPoint {
  id: string;
  timestamp: string;
  prompt: string;
  sessionId?: string;
  isCurrentSession: boolean;
}

/**
 * CLIRunner provides methods to execute the Entire CLI binary.
 */
export class CLIRunner {
  private readonly binaryPath: string;
  private readonly repoPath: string;

  constructor(repoPath: string) {
    const binaryPath = process.env.ENTIRE_BIN_PATH;
    if (!binaryPath) {
      throw new Error('ENTIRE_BIN_PATH environment variable not set. Did global setup run?');
    }
    this.binaryPath = binaryPath;
    this.repoPath = repoPath;
  }

  /**
   * Execute an Entire CLI command.
   */
  private exec(args: string[], env: Record<string, string> = {}): string {
    const options: ExecSyncOptions = {
      cwd: this.repoPath,
      encoding: 'utf-8',
      stdio: ['pipe', 'pipe', 'pipe'],
      env: {
        ...process.env,
        ...env,
      },
    };

    const cmd = `"${this.binaryPath}" ${args.map(a => `"${a}"`).join(' ')}`;

    try {
      const result = execSync(cmd, {
        ...options,
        shell: '/bin/bash',
      });
      return (result as string).trim();
    } catch (error) {
      const execError = error as { stdout?: Buffer | string; stderr?: Buffer | string };
      const stdout = execError.stdout?.toString() || '';
      const stderr = execError.stderr?.toString() || '';
      throw new Error(`entire ${args.join(' ')} failed:\nstdout: ${stdout}\nstderr: ${stderr}`);
    }
  }

  /**
   * Enable Entire in the repository with the specified strategy.
   */
  enable(strategy = 'manual-commit'): void {
    this.exec(['enable', '--strategy', strategy]);
  }

  /**
   * Disable Entire in the repository.
   */
  disable(): void {
    this.exec(['disable']);
  }

  /**
   * Get the list of rewind points.
   */
  rewindList(): RewindPoint[] {
    const output = this.exec(['rewind', '--list', '--json']);

    if (!output || output === '[]') {
      return [];
    }

    try {
      const data = JSON.parse(output);
      return data.map((item: Record<string, unknown>) => ({
        id: item.id as string,
        timestamp: item.timestamp as string,
        prompt: item.prompt as string,
        sessionId: item.session_id as string | undefined,
        isCurrentSession: item.is_current_session as boolean,
      }));
    } catch {
      // If JSON parsing fails, try to parse text output
      return this.parseTextRewindList(output);
    }
  }

  /**
   * Parse text-based rewind list output (fallback).
   */
  private parseTextRewindList(output: string): RewindPoint[] {
    const points: RewindPoint[] = [];
    const lines = output.split('\n');

    for (const line of lines) {
      // Expected format: "1. [timestamp] prompt text (session: id)"
      const match = line.match(/^\d+\.\s+\[([^\]]+)\]\s+(.+?)(?:\s+\(session:\s+([^)]+)\))?$/);
      if (match) {
        points.push({
          id: (points.length + 1).toString(),
          timestamp: match[1],
          prompt: match[2],
          sessionId: match[3],
          isCurrentSession: true, // Assume current session for text output
        });
      }
    }

    return points;
  }

  /**
   * Rewind to a specific checkpoint.
   */
  rewind(checkpointId: string): void {
    this.exec(['rewind', '--to', checkpointId]);
  }

  /**
   * Get the current strategy.
   */
  getStrategy(): string {
    const output = this.exec(['status', '--json']);
    try {
      const data = JSON.parse(output);
      return data.strategy || 'unknown';
    } catch {
      return 'unknown';
    }
  }

  /**
   * Check if Entire is enabled in the repository.
   */
  isEnabled(): boolean {
    try {
      this.exec(['status']);
      return true;
    } catch {
      return false;
    }
  }
}

/**
 * Create a CLI runner for a test repository.
 */
export function createCLIRunner(repoPath: string): CLIRunner {
  return new CLIRunner(repoPath);
}

import { expect } from 'vitest';
import type { TestRepo } from './git-repo.js';

/**
 * Assert that a shadow branch exists for the given HEAD hash.
 * Shadow branches are named: entire/<commit-hash[:7]>
 */
export function assertShadowBranchExists(repo: TestRepo, headHash: string): void {
  const shortHash = headHash.substring(0, 7);
  const shadowBranch = `entire/${shortHash}`;

  const exists = repo.branchExists(shadowBranch);
  expect(exists, `Shadow branch ${shadowBranch} should exist`).toBe(true);
}

/**
 * Assert that the metadata branch exists.
 * The metadata branch is: entire/sessions
 */
export function assertMetadataBranchExists(repo: TestRepo): void {
  const exists = repo.branchExists('entire/sessions');
  expect(exists, 'Metadata branch entire/sessions should exist').toBe(true);
}

/**
 * Assert that checkpoint metadata exists on the metadata branch.
 * Metadata is stored at sharded path: <id[:2]>/<id[2:]>/metadata.json
 */
export function assertCheckpointMetadata(
  repo: TestRepo,
  checkpointId: string
): void {
  const shard = checkpointId.substring(0, 2);
  const rest = checkpointId.substring(2);
  const metadataPath = `${shard}/${rest}/metadata.json`;

  const content = repo.getFileAtRef('entire/sessions', metadataPath);
  expect(content, `Checkpoint metadata should exist at ${metadataPath}`).not.toBeNull();

  // Parse and validate metadata structure
  const metadata = JSON.parse(content!);
  expect(metadata.checkpoint_id).toBe(checkpointId);
  expect(metadata.session_id).toBeDefined();
  expect(metadata.strategy).toBeDefined();
}

/**
 * Assert that a file exists with specific content at a checkpoint.
 */
export function assertFileAtCheckpoint(
  repo: TestRepo,
  branch: string,
  filePath: string,
  expectedContent: string
): void {
  const content = repo.getFileAtRef(branch, filePath);
  expect(content, `File ${filePath} should exist on ${branch}`).not.toBeNull();
  expect(content).toBe(expectedContent);
}

/**
 * Assert that a file exists at a checkpoint (content doesn't matter).
 */
export function assertFileExistsAtCheckpoint(
  repo: TestRepo,
  branch: string,
  filePath: string
): void {
  const content = repo.getFileAtRef(branch, filePath);
  expect(content, `File ${filePath} should exist on ${branch}`).not.toBeNull();
}

/**
 * Assert that a file does NOT exist at a checkpoint.
 */
export function assertFileNotAtCheckpoint(
  repo: TestRepo,
  branch: string,
  filePath: string
): void {
  const content = repo.getFileAtRef(branch, filePath);
  expect(content, `File ${filePath} should NOT exist on ${branch}`).toBeNull();
}

/**
 * Assert that a commit has the Entire-Checkpoint trailer.
 */
export function assertHasCheckpointTrailer(repo: TestRepo, ref: string): string {
  const trailers = repo.getCommitTrailers(ref);
  const checkpointId = trailers.get('Entire-Checkpoint');
  expect(checkpointId, 'Commit should have Entire-Checkpoint trailer').toBeDefined();
  expect(checkpointId).toMatch(/^[a-f0-9]{12}$/);
  return checkpointId!;
}

/**
 * Assert that shadow branch has session metadata files.
 */
export function assertShadowBranchHasMetadata(
  repo: TestRepo,
  headHash: string,
  sessionId: string
): void {
  const shortHash = headHash.substring(0, 7);
  const shadowBranch = `entire/${shortHash}`;

  // Check for session metadata directory
  const metadataPath = `.entire/metadata/${sessionId}`;
  const files = repo.listFilesAtRef(shadowBranch);

  const hasMetadata = files.some(f => f.startsWith(metadataPath));
  expect(hasMetadata, `Shadow branch should have metadata at ${metadataPath}`).toBe(true);
}

/**
 * Assert that a session transcript exists.
 */
export function assertSessionTranscriptExists(
  repo: TestRepo,
  branch: string,
  sessionId: string
): void {
  const transcriptPath = `.entire/metadata/${sessionId}/full.jsonl`;
  const content = repo.getFileAtRef(branch, transcriptPath);
  expect(content, `Session transcript should exist at ${transcriptPath}`).not.toBeNull();
  expect(content!.length).toBeGreaterThan(0);
}

/**
 * Get all shadow branches in the repository.
 */
export function getShadowBranches(repo: TestRepo): string[] {
  const branches = repo.listBranches();
  return branches.filter(b => b.startsWith('entire/') && !b.includes('sessions'));
}

/**
 * Assert that the working directory matches expected state.
 */
export function assertWorkingDirectory(
  repo: TestRepo,
  expectedFiles: Record<string, string | null>
): void {
  for (const [path, expectedContent] of Object.entries(expectedFiles)) {
    if (expectedContent === null) {
      expect(repo.fileExists(path), `File ${path} should NOT exist`).toBe(false);
    } else {
      expect(repo.fileExists(path), `File ${path} should exist`).toBe(true);
      const actualContent = repo.readFile(path);
      expect(actualContent, `File ${path} content mismatch`).toBe(expectedContent);
    }
  }
}

