   118→# Commit-msg hook: strip trailer if no user content (allows aborting empty commits)
   119→%s hooks git commit-msg "$1" || exit 1
   120→`, entireHookMarker, cmdPrefix)
   121→
   122→	written, err = writeHookFile(commitMsgPath, commitMsgContent)
   123→	if err != nil {
   124→		return 0, fmt.Errorf("failed to install commit-msg hook: %w", err)
   125→	}
   126→	if written {
   127→		installedCount++
   128→	}
   129→
   130→	// Install post-commit hook
   131→	postCommitPath := filepath.Join(hooksDir, "post-commit")
   132→	postCommitContent := fmt.Sprintf(`#!/bin/sh
   133→# %s
   134→# Post-commit hook: condense session data if commit has Entire-Checkpoint trailer
   135→%s hooks git post-commit 2>/dev/null || true
   136→`, entireHookMarker, cmdPrefix)
   137→
   138→	written, err = writeHookFile(postCommitPath, postCommitContent)
   139→	if err != nil {
   140→		return 0, fmt.Errorf("failed to install post-commit hook: %w", err)
   141→	}
   142→	if written {
   143→		installedCount++
   144→	}
