   171→// writeHookFile writes a hook file if it doesn't exist or has different content.
   172→// Returns true if the file was written, false if it already had the same content.
   173→func writeHookFile(path, content string) (bool, error) {
   174→	// Check if file already exists with same content
   175→	existing, err := os.ReadFile(path) //nolint:gosec // path is controlled
   176→	if err == nil && string(existing) == content {
   177→		return false, nil // Already up to date
   178→	}
   179→
   180→	// Git hooks must be executable (0o755)
   181→	if err := os.WriteFile(path, []byte(content), 0o755); err != nil { //nolint:gosec // Git hooks require executable permissions
   182→		return false, fmt.Errorf("failed to write hook file %s: %w", path, err)
   183→	}
   184→	return true, nil
   185→}
