   187→// RemoveGitHook removes all Entire CLI git hooks from the repository.
   188→// Returns the number of hooks removed.
   189→func RemoveGitHook() (int, error) {
   190→	gitDir, err := GetGitDir()
   191→	if err != nil {
   192→		return 0, err
   193→	}
   194→
   195→	removed := 0
   196→	var removeErrors []string
   197→
   198→	for _, hook := range gitHookNames {
   199→		hookPath := filepath.Join(gitDir, "hooks", hook)
   200→		data, err := os.ReadFile(hookPath) //nolint:gosec // path is controlled
   201→		if err != nil {
   202→			continue // Hook doesn't exist
   203→		}
   204→
   205→		if strings.Contains(string(data), entireHookMarker) {
   206→			if err := os.Remove(hookPath); err != nil {
   207→				removeErrors = append(removeErrors, fmt.Sprintf("%s: %v", hook, err))
   208→			} else {
   209→				removed++
   210→			}
   211→		}
   212→	}
   213→
   214→	if len(removeErrors) > 0 {
   215→		return removed, fmt.Errorf("failed to remove hooks: %s", strings.Join(removeErrors, "; "))
   216→	}
   217→	return removed, nil
   218→}
