   213→// UninstallHooks removes Entire hooks from Claude Code settings.
   214→func (c *ClaudeCodeAgent) UninstallHooks() error {
   215→	// Use repo root to find .claude directory when run from a subdirectory
   216→	repoRoot, err := paths.RepoRoot()
   217→	if err != nil {
   218→		repoRoot = "." // Fallback to CWD if not in a git repo
   219→	}
   220→	settingsPath := filepath.Join(repoRoot, ".claude", ClaudeSettingsFileName)
   221→	data, err := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from repo root + fixed path
   222→	if err != nil {
   223→		return nil //nolint:nilerr // No settings file means nothing to uninstall
   224→	}
   225→
   226→	var rawSettings map[string]json.RawMessage
   227→	if err := json.Unmarshal(data, &rawSettings); err != nil {
   228→		return fmt.Errorf("failed to parse settings.json: %w", err)
   229→	}
   230→
   231→	var settings ClaudeSettings
   232→	if hooksRaw, ok := rawSettings["hooks"]; ok {
   233→		if err := json.Unmarshal(hooksRaw, &settings.Hooks); err != nil {
   234→			return fmt.Errorf("failed to parse hooks: %w", err)
   235→		}
   236→	}
   237→
   238→	// Remove Entire hooks from all hook types
   239→	settings.Hooks.SessionStart = removeEntireHooks(settings.Hooks.SessionStart)
   240→	settings.Hooks.Stop = removeEntireHooks(settings.Hooks.Stop)
   241→	settings.Hooks.UserPromptSubmit = removeEntireHooks(settings.Hooks.UserPromptSubmit)
   242→	settings.Hooks.PreToolUse = removeEntireHooksFromMatchers(settings.Hooks.PreToolUse)
   243→	settings.Hooks.PostToolUse = removeEntireHooksFromMatchers(settings.Hooks.PostToolUse)
   244→
   245→	// Also remove the metadata deny rule from permissions
   246→	var rawPermissions map[string]json.RawMessage
   247→	if permRaw, ok := rawSettings["permissions"]; ok {
   248→		if err := json.Unmarshal(permRaw, &rawPermissions); err != nil {
   249→			// If parsing fails, just skip permissions cleanup
   250→			rawPermissions = nil
   251→		}
   252→	}
   253→
   254→	if rawPermissions != nil {
   255→		if denyRaw, ok := rawPermissions["deny"]; ok {
   256→			var denyRules []string
   257→			if err := json.Unmarshal(denyRaw, &denyRules); err == nil {
   258→				// Filter out the metadata deny rule
   259→				filteredRules := make([]string, 0, len(denyRules))
   260→				for _, rule := range denyRules {
   261→					if rule != metadataDenyRule {
   262→						filteredRules = append(filteredRules, rule)
   263→					}
   264→				}
   265→				if len(filteredRules) > 0 {
   266→					denyJSON, err := json.Marshal(filteredRules)
   267→					if err == nil {
   268→						rawPermissions["deny"] = denyJSON
   269→					}
   270→				} else {
   271→					// Remove empty deny array
   272→					delete(rawPermissions, "deny")
   273→				}
   274→			}
   275→		}
   276→
   277→		// If permissions is empty, remove it entirely
   278→		if len(rawPermissions) > 0 {
   279→			permJSON, err := json.Marshal(rawPermissions)
   280→			if err == nil {
   281→				rawSettings["permissions"] = permJSON
   282→			}
   283→		} else {
   284→			delete(rawSettings, "permissions")
   285→		}
   286→	}
   287→
   288→	// Marshal hooks back
   289→	hooksJSON, err := json.Marshal(settings.Hooks)
   290→	if err != nil {
   291→		return fmt.Errorf("failed to marshal hooks: %w", err)
   292→	}
   293→	rawSettings["hooks"] = hooksJSON
   294→
   295→	// Write back
   296→	output, err := jsonutil.MarshalIndentWithNewline(rawSettings, "", "  ")
   297→	if err != nil {
   298→		return fmt.Errorf("failed to marshal settings: %w", err)
   299→	}
   300→	if err := os.WriteFile(settingsPath, output, 0o600); err != nil {
   301→		return fmt.Errorf("failed to write settings.json: %w", err)
   302→	}
   303→	return nil
   304→}
