   345→// Helper functions for hook management
   346→
   347→func hookCommandExists(matchers []ClaudeHookMatcher, command string) bool {
   348→	for _, matcher := range matchers {
   349→		for _, hook := range matcher.Hooks {
   350→			if hook.Command == command {
   351→				return true
   352→			}
   353→		}
   354→	}
   355→	return false
   356→}
   357→
   358→func hookCommandExistsWithMatcher(matchers []ClaudeHookMatcher, matcherName, command string) bool {
   359→	for _, matcher := range matchers {
   360→		if matcher.Matcher == matcherName {
   361→			for _, hook := range matcher.Hooks {
   362→				if hook.Command == command {
   363→					return true
   364→				}
   365→			}
   366→		}
   367→	}
   368→	return false
   369→}
   370→
   371→func addHookToMatcher(matchers []ClaudeHookMatcher, matcherName, command string) []ClaudeHookMatcher {
   372→	entry := ClaudeHookEntry{
   373→		Type:    "command",
   374→		Command: command,
   375→	}
   376→
   377→	// If no matcher name, add to a matcher with empty string
   378→	if matcherName == "" {
   379→		for i, matcher := range matchers {
   380→			if matcher.Matcher == "" {
   381→				matchers[i].Hooks = append(matchers[i].Hooks, entry)
   382→				return matchers
   383→			}
   384→		}
   385→		return append(matchers, ClaudeHookMatcher{
   386→			Matcher: "",
   387→			Hooks:   []ClaudeHookEntry{entry},
   388→		})
   389→	}
   390→
   391→	// Find or create matcher with the given name
   392→	for i, matcher := range matchers {
   393→		if matcher.Matcher == matcherName {
   394→			matchers[i].Hooks = append(matchers[i].Hooks, entry)
   395→			return matchers
   396→		}
   397→	}
   398→
   399→	return append(matchers, ClaudeHookMatcher{
   400→		Matcher: matcherName,
   401→		Hooks:   []ClaudeHookEntry{entry},
   402→	})
   403→}
