   405→// isEntireHook checks if a command is an Entire hook (old or new format)
   406→func isEntireHook(command string) bool {
   407→	for _, prefix := range entireHookPrefixes {
   408→		if strings.HasPrefix(command, prefix) {
   409→			return true
   410→		}
