import { query, type Message } from '@anthropic-ai/claude-agent-sdk';
import { mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { TestRepo } from './git-repo.js';
import { CLIRunner } from './cli-runner.js';

export interface TestEnvOptions {
  /** Strategy to use (default: 'manual-commit') */
  strategy?: string;
  /** Skip Entire CLI initialization */
  skipEnable?: boolean;
}

export interface ClaudeResult {
  /** All messages from the Claude session */
  messages: Message[];
  /** Final result message (if successful) */
  result?: string;
  /** Whether the session completed successfully */
  success: boolean;
  /** Error message if session failed */
  error?: string;
}

/**
 * TestEnv provides a complete test environment with:
 * - Isolated git repository
 * - Claude Code hooks configuration
 * - Entire CLI initialized with specified strategy
 * - Method to run Claude sessions via Agent SDK
 */
export class TestEnv {
  public readonly repo: TestRepo;
  public readonly cli: CLIRunner;
  private readonly binaryPath: string;

  private constructor(repo: TestRepo, cli: CLIRunner, binaryPath: string) {
    this.repo = repo;
    this.cli = cli;
    this.binaryPath = binaryPath;
  }

  /**
   * Create a new test environment.
   */
  static async create(options: TestEnvOptions = {}): Promise<TestEnv> {
    const strategy = options.strategy ?? 'manual-commit';

    // Get CLI binary path from environment
    const binaryPath = process.env.ENTIRE_BIN_PATH;
    if (!binaryPath) {
      throw new Error('ENTIRE_BIN_PATH not set. Did global setup run?');
    }

    // Create isolated git repo
    const repo = new TestRepo();
    const cli = new CLIRunner(repo.path);

    const env = new TestEnv(repo, cli, binaryPath);

    if (!options.skipEnable) {
      // Enable Entire CLI with the specified strategy
      cli.enable(strategy);

      // Set up Claude Code hooks configuration
      env.setupClaudeHooks();
    }

    return env;
  }

  /**
   * Set up Claude Code hooks in .claude/settings.json.
   * These hooks point to the built CLI binary for testing.
   */
  private setupClaudeHooks(): void {
    const claudeDir = join(this.repo.path, '.claude');
    mkdirSync(claudeDir, { recursive: true });

    const settings = {
      hooks: {
        SessionStart: [
          {
            matcher: '',
            hooks: [
              {
                type: 'command',
                command: `${this.binaryPath} hooks claude-code session-start`,
              },
            ],
          },
        ],
        Stop: [
          {
            matcher: '',
            hooks: [
              {
                type: 'command',
                command: `${this.binaryPath} hooks claude-code stop`,
              },
            ],
          },
        ],
        UserPromptSubmit: [
          {
            matcher: '',
            hooks: [
              {
                type: 'command',
                command: `${this.binaryPath} hooks claude-code user-prompt-submit`,
              },
            ],
          },
        ],
        PreToolUse: [
          {
            matcher: 'Task',
            hooks: [
              {
                type: 'command',
                command: `${this.binaryPath} hooks claude-code pre-task`,
              },
            ],
          },
        ],
        PostToolUse: [
          {
            matcher: 'Task',
            hooks: [
              {
                type: 'command',
                command: `${this.binaryPath} hooks claude-code post-task`,
              },
            ],
          },
          {
            matcher: 'TodoWrite',
            hooks: [
              {
                type: 'command',
                command: `${this.binaryPath} hooks claude-code post-todo`,
              },
            ],
          },
        ],
      },
      permissions: {
        deny: ['Read(./.entire/metadata/**)'],
      },
    };

    writeFileSync(
      join(claudeDir, 'settings.json'),
      JSON.stringify(settings, null, 2)
    );
  }

  /**
   * Run Claude with the given prompt.
   * Returns all messages from the session and the final result.
   */
  async runClaude(prompt: string): Promise<ClaudeResult> {
    const messages: Message[] = [];
    let result: string | undefined;
    let success = false;
    let error: string | undefined;

    try {
      for await (const message of query({
        prompt,
        options: {
          cwd: this.repo.path,
          settingSources: ['project'], // Load .claude/settings.json hooks
          allowedTools: ['Read', 'Write', 'Edit', 'Bash', 'Glob', 'Grep'],
          permissionMode: 'acceptEdits', // Auto-approve for E2E tests
          maxTurns: 10, // Limit turns for testing
        },
      })) {
        messages.push(message);

        if (message.type === 'result') {
          if (message.subtype === 'success') {
            result = message.result;
            success = true;
          } else if (message.subtype === 'error') {
            error = message.error;
            success = false;
          }
        }
      }
    } catch (err) {
      error = err instanceof Error ? err.message : String(err);
      success = false;
    }

    return { messages, result, success, error };
  }

  /**
   * Run Claude with a simple file creation task.
   * This is a convenience method for common test scenarios.
   */
  async createFile(filename: string, content: string): Promise<ClaudeResult> {
    return this.runClaude(
      `Create a file named "${filename}" with the following content:\n\n${content}\n\nJust create the file, nothing else.`
    );
  }

  /**
   * Clean up the test environment.
   */
  cleanup(): void {
    this.repo.cleanup();
  }
}

/**
 * Create a test environment for a test.
 * Use with afterEach to ensure cleanup.
 */
export async function createTestEnv(
  options: TestEnvOptions = {}
): Promise<TestEnv> {
  return TestEnv.create(options);
}

import { describe, it, expect, afterEach, beforeEach } from 'vitest';
import { createTestEnv, type TestEnv } from '../utils/test-env.js';
import {
  assertShadowBranchExists,
  getShadowBranches,
} from '../utils/git-assertions.js';

describe('Checkpoint Creation', () => {
  let env: TestEnv;

  beforeEach(async () => {
    env = await createTestEnv({ strategy: 'manual-commit' });
  });

  afterEach(() => {
    env?.cleanup();
  });

  it('creates shadow branch after Claude session', async () => {
    // Record HEAD hash before Claude session
    const headHash = env.repo.getHeadHash();

    // Run Claude to create a file
    const result = await env.createFile('hello.txt', 'Hello World');
    expect(result.success).toBe(true);

    // Verify the file was created
    expect(env.repo.fileExists('hello.txt')).toBe(true);
    expect(env.repo.readFile('hello.txt')).toContain('Hello World');

    // Verify shadow branch was created
    assertShadowBranchExists(env.repo, headHash);
  });

  it('lists checkpoints after Claude session', async () => {
    // Run Claude to create a file
    const result = await env.createFile('test.txt', 'Test content');
    expect(result.success).toBe(true);

    // Get rewind points
    const rewindPoints = env.cli.rewindList();

    // Should have at least one checkpoint
    expect(rewindPoints.length).toBeGreaterThan(0);

    // First checkpoint should exist
    const checkpoint = rewindPoints[0];
    expect(checkpoint.id).toBeDefined();
    expect(checkpoint.timestamp).toBeDefined();
  });

  it('creates checkpoints for multiple file operations', async () => {
    const headHash = env.repo.getHeadHash();

    // First Claude session - create file A
    let result = await env.createFile('a.txt', 'File A content');
    expect(result.success).toBe(true);

    // Second Claude session - create file B
    result = await env.createFile('b.txt', 'File B content');
    expect(result.success).toBe(true);

    // Verify shadow branch exists
    assertShadowBranchExists(env.repo, headHash);

    // Get all checkpoints
    const rewindPoints = env.cli.rewindList();

    // Should have checkpoints for both sessions
    expect(rewindPoints.length).toBeGreaterThanOrEqual(2);

    // Both files should exist in working directory
    expect(env.repo.fileExists('a.txt')).toBe(true);
    expect(env.repo.fileExists('b.txt')).toBe(true);
  });

  it('creates shadow branch with correct naming convention', async () => {
    const headHash = env.repo.getHeadHash();
    const shortHash = headHash.substring(0, 7);

    // Run Claude session
    const result = await env.createFile('naming.txt', 'Test naming');
    expect(result.success).toBe(true);

    // Get all shadow branches
    const shadowBranches = getShadowBranches(env.repo);

    // Should have exactly one shadow branch with correct format
    const expectedBranch = `entire/${shortHash}`;
    expect(shadowBranches).toContain(expectedBranch);
  });

  it('preserves session metadata in checkpoint', async () => {
    // Run Claude session with identifiable prompt
    const result = await env.runClaude('Create a file called metadata-test.txt with content "metadata test"');
    expect(result.success).toBe(true);

    // Get rewind points
    const rewindPoints = env.cli.rewindList();
    expect(rewindPoints.length).toBeGreaterThan(0);

    // Check that the checkpoint has prompt metadata
    const checkpoint = rewindPoints[0];
    expect(checkpoint.prompt).toBeDefined();
  });
});

import { describe, it, expect, afterEach, beforeEach } from 'vitest';
import { createTestEnv, type TestEnv } from '../utils/test-env.js';
import { assertWorkingDirectory } from '../utils/git-assertions.js';

describe('Rewind Functionality', () => {
  let env: TestEnv;

  beforeEach(async () => {
    env = await createTestEnv({ strategy: 'manual-commit' });
  });

  afterEach(() => {
    env?.cleanup();
  });

  it('restores files from previous checkpoint', async () => {
    // Create first file with Claude
    let result = await env.createFile('a.txt', 'File A content');
    expect(result.success).toBe(true);

    // Get checkpoint after first file
    const checkpointsAfterA = env.cli.rewindList();
    expect(checkpointsAfterA.length).toBeGreaterThan(0);
    const checkpoint1 = checkpointsAfterA[0];

    // Create second file with Claude
    result = await env.createFile('b.txt', 'File B content');
    expect(result.success).toBe(true);

    // Verify both files exist
    expect(env.repo.fileExists('a.txt')).toBe(true);
    expect(env.repo.fileExists('b.txt')).toBe(true);

    // Rewind to first checkpoint
    env.cli.rewind(checkpoint1.id);

    // Verify file state: a.txt should exist, b.txt should not
    expect(env.repo.fileExists('a.txt')).toBe(true);
    expect(env.repo.fileExists('b.txt')).toBe(false);
  });

  it('restores file content from checkpoint', async () => {
    // Create file with initial content
    let result = await env.createFile('content.txt', 'Version 1');
    expect(result.success).toBe(true);

    // Get checkpoint after initial version
    const checkpointsV1 = env.cli.rewindList();
    const checkpointV1 = checkpointsV1[0];

    // Modify file content with Claude
    result = await env.runClaude(
      'Edit the file content.txt and change its content to "Version 2"'
    );
    expect(result.success).toBe(true);

    // Verify new content
    const newContent = env.repo.readFile('content.txt');
    expect(newContent).toContain('Version 2');

    // Rewind to V1
    env.cli.rewind(checkpointV1.id);

    // Verify original content is restored
    const restoredContent = env.repo.readFile('content.txt');
    expect(restoredContent).toContain('Version 1');
  });

  it('can rewind multiple times', async () => {
    // Create file A
    await env.createFile('a.txt', 'A');
    const checkpointsA = env.cli.rewindList();
    const checkpointA = checkpointsA[0];

    // Create file B
    await env.createFile('b.txt', 'B');
    const checkpointsB = env.cli.rewindList();
    const checkpointB = checkpointsB[0];

    // Create file C
    await env.createFile('c.txt', 'C');

    // Verify all files exist
    assertWorkingDirectory(env.repo, {
      'a.txt': 'A',
      'b.txt': 'B',
      'c.txt': 'C',
    });

    // Rewind to checkpoint B (after creating A and B)
    env.cli.rewind(checkpointB.id);
    expect(env.repo.fileExists('a.txt')).toBe(true);
    expect(env.repo.fileExists('b.txt')).toBe(true);
    expect(env.repo.fileExists('c.txt')).toBe(false);

    // Rewind to checkpoint A (only A exists)
    env.cli.rewind(checkpointA.id);
    expect(env.repo.fileExists('a.txt')).toBe(true);
    expect(env.repo.fileExists('b.txt')).toBe(false);
    expect(env.repo.fileExists('c.txt')).toBe(false);
  });

  it('preserves untracked files during rewind', async () => {
    // Create a file without Claude
    env.repo.writeFile('manual.txt', 'Created manually');

    // Create file with Claude
    await env.createFile('claude.txt', 'Created by Claude');
    const checkpoints = env.cli.rewindList();
    const checkpoint = checkpoints[0];

    // Create another file with Claude
    await env.createFile('claude2.txt', 'Also by Claude');

    // Rewind
    env.cli.rewind(checkpoint.id);

    // Manual file should still exist (it's untracked/gitignored)
    expect(env.repo.fileExists('manual.txt')).toBe(true);

    // First Claude file should exist
    expect(env.repo.fileExists('claude.txt')).toBe(true);

    // Second Claude file should be gone
    expect(env.repo.fileExists('claude2.txt')).toBe(false);
  });

  it('rewind list shows chronological order', async () => {
    // Create multiple files in sequence
    await env.createFile('first.txt', 'First');
    await env.createFile('second.txt', 'Second');
    await env.createFile('third.txt', 'Third');

    // Get all checkpoints
    const checkpoints = env.cli.rewindList();

    // Should have at least 3 checkpoints
    expect(checkpoints.length).toBeGreaterThanOrEqual(3);

    // Verify timestamps are in order (most recent first)
    for (let i = 1; i < checkpoints.length; i++) {
      const current = new Date(checkpoints[i].timestamp);
      const previous = new Date(checkpoints[i - 1].timestamp);
      expect(previous.getTime()).toBeGreaterThanOrEqual(current.getTime());
    }
  });
});

import { describe, it, expect, afterEach, beforeEach } from 'vitest';
import { createTestEnv, type TestEnv } from '../utils/test-env.js';
import {
  assertMetadataBranchExists,
  assertHasCheckpointTrailer,
  assertCheckpointMetadata,
} from '../utils/git-assertions.js';

describe('Commit and Condensation', () => {
  let env: TestEnv;

  beforeEach(async () => {
    env = await createTestEnv({ strategy: 'manual-commit' });
  });

  afterEach(() => {
    env?.cleanup();
  });

  it('condenses to entire/sessions on user commit', async () => {
    // Create file with Claude
    const result = await env.createFile('main.go', 'package main\n\nfunc main() {\n\tprintln("Hello")\n}\n');
    expect(result.success).toBe(true);

    // Verify file exists
    expect(env.repo.fileExists('main.go')).toBe(true);

    // Make a user commit
    env.repo.git('add', 'main.go');
    env.repo.git('commit', '-m', 'Add main.go');

    // Verify entire/sessions branch was created
    assertMetadataBranchExists(env.repo);
  });

  it('adds Entire-Checkpoint trailer to user commit', async () => {
    // Create file with Claude
    const result = await env.createFile('feature.ts', 'export const feature = true;');
    expect(result.success).toBe(true);

    // Make a user commit
    env.repo.git('add', 'feature.ts');
    env.repo.git('commit', '-m', 'Add feature');

    // Verify commit has the checkpoint trailer
    const checkpointId = assertHasCheckpointTrailer(env.repo, 'HEAD');

    // Checkpoint ID should be 12 hex characters
    expect(checkpointId).toMatch(/^[a-f0-9]{12}$/);
  });

  it('links commit to metadata via checkpoint ID', async () => {
    // Create file with Claude
    const result = await env.createFile('linked.txt', 'Linked content');
    expect(result.success).toBe(true);

    // Make a user commit
    env.repo.git('add', 'linked.txt');
    env.repo.git('commit', '-m', 'Add linked file');

    // Get the checkpoint ID from the commit trailer
    const checkpointId = assertHasCheckpointTrailer(env.repo, 'HEAD');

    // Verify metadata exists on entire/sessions branch
    assertCheckpointMetadata(env.repo, checkpointId);
  });

  it('condenses multiple sessions to same checkpoint', async () => {
    // Create first file with Claude
    let result = await env.createFile('first.txt', 'First file');
    expect(result.success).toBe(true);

    // Create second file with Claude (same base commit, no user commit yet)
    result = await env.createFile('second.txt', 'Second file');
    expect(result.success).toBe(true);

    // Single user commit captures both sessions
    env.repo.git('add', '.');
    env.repo.git('commit', '-m', 'Add files from multiple sessions');

    // Verify metadata branch exists
    assertMetadataBranchExists(env.repo);

    // Get checkpoint ID
    const checkpointId = assertHasCheckpointTrailer(env.repo, 'HEAD');

    // Verify metadata exists
    assertCheckpointMetadata(env.repo, checkpointId);
  });

  it('preserves session history across multiple commits', async () => {
    // First commit cycle
    await env.createFile('commit1.txt', 'Commit 1');
    env.repo.git('add', 'commit1.txt');
    env.repo.git('commit', '-m', 'First commit');

    const checkpoint1 = assertHasCheckpointTrailer(env.repo, 'HEAD');

    // Second commit cycle
    await env.createFile('commit2.txt', 'Commit 2');
    env.repo.git('add', 'commit2.txt');
    env.repo.git('commit', '-m', 'Second commit');

    const checkpoint2 = assertHasCheckpointTrailer(env.repo, 'HEAD');

    // Both checkpoints should have metadata
    assertCheckpointMetadata(env.repo, checkpoint1);
    assertCheckpointMetadata(env.repo, checkpoint2);

    // Checkpoint IDs should be different
    expect(checkpoint1).not.toBe(checkpoint2);
  });

  it('maintains clean commit messages with only trailer', async () => {
    // Create file with Claude
    const result = await env.createFile('clean.txt', 'Clean content');
    expect(result.success).toBe(true);

    // Make commit with specific message
    env.repo.git('add', 'clean.txt');
    env.repo.git('commit', '-m', 'My custom commit message');

    // Get full commit message
    const commitMessage = env.repo.getCommitMessage('HEAD');

    // Message should contain our custom text
    expect(commitMessage).toContain('My custom commit message');

    // And should have the Entire-Checkpoint trailer
    expect(commitMessage).toMatch(/Entire-Checkpoint: [a-f0-9]{12}/);

    // But should NOT have other Entire metadata cluttering it
    expect(commitMessage).not.toContain('Entire-Session:');
    expect(commitMessage).not.toContain('Entire-Strategy:');
  });

  it('handles empty Claude session gracefully', async () => {
    // Just verify environment is set up (no Claude interaction)
    expect(env.repo.fileExists('.gitignore')).toBe(true);

    // Make a commit without any Claude changes
    env.repo.writeFile('manual.txt', 'Manual content');
    env.repo.git('add', 'manual.txt');
    env.repo.git('commit', '-m', 'Manual commit');

    // The commit should succeed but may not have Entire-Checkpoint trailer
    // (depends on whether there was an active session)
    const commitMessage = env.repo.getCommitMessage('HEAD');
    expect(commitMessage).toContain('Manual commit');
  });
});

